<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Что такое отчёт о расходах целевых средств?", "acceptedAnswer": {"@type": "Answer", "text": "Это отчётный документ, в котором получатель субсидии, гранта или исполнитель контракта показывает фактические расходы целевых средств под казначейским сопровождением. Его формируют, как правило, ежеквартально нарастающим итогом в «Электронном бюджете»."}}, {"@type": "Question", "name": "Чем отчёт о расходах отличается от сведений об операциях?", "acceptedAnswer": {"@type": "Answer", "text": "Сведения об операциях составляют до расходования — они нужны для санкционирования платежей. Отчёт о расходах формируют после расходования: он подтверждает уже совершённые операции. Это разные документы на разных этапах."}}, {"@type": "Question", "name": "Как часто сдают отчёт о расходах?", "acceptedAnswer": {"@type": "Answer", "text": "Как правило, ежеквартально, нарастающим итогом с начала финансового года. Точные сроки и периодичность определяет соглашение и типовая форма, поэтому их нужно сверять с текстом соглашения."}}, {"@type": "Question", "name": "Где заполняется отчёт?", "acceptedAnswer": {"@type": "Answer", "text": "В государственной интегрированной системе «Электронный бюджет». Отчёт формируется по соглашению или контракту и подписывается квалифицированной электронной подписью."}}, {"@type": "Question", "name": "Какие коды указывать в отчёте?", "acceptedAnswer": {"@type": "Answer", "text": "Коды направления расходования по приложению № 3 к приказу Минфина № 214н. Они должны совпадать с кодами, заявленными в сведениях об операциях, иначе возникнут расхождения."}}, {"@type": "Question", "name": "Почему отчёт возвращают на доработку?", "acceptedAnswer": {"@type": "Answer", "text": "Чаще всего из-за несоответствия кодов, расхождения факта с остатком на лицевом счёте и арифметических ошибок нарастающего итога. До исправления отчётный период не закрывается."}}, {"@type": "Question", "name": "Что грозит за несданный отчёт?", "acceptedAnswer": {"@type": "Answer", "text": "По соглашениям о субсидиях и грантах возможны приостановление перечислений и требование вернуть средства. Недостоверная отчётность может стать предметом последующего контроля казначейства."}}, {"@type": "Question", "name": "Как связаны отчёт и выписка из лицевого счёта?", "acceptedAnswer": {"@type": "Answer", "text": "Остаток целевых средств в отчёте сверяют с выпиской из лицевого счёта казначейства. Если данные расходятся, это сигнал об ошибке в отчёте или в учёте."}}, {"@type": "Question", "name": "Как подтверждается расход целевых средств при казначейском сопровождении?", "acceptedAnswer": {"@type": "Answer", "text": "Каждый расход целевых средств подтверждается документами (договор, акт, счёт) и отражается в Сведениях об операциях с целевыми средствами с указанием кода направления по приказу № 214н. Без подтверждающих документов и корректного кода казначейство приостанавливает платёж."}}]}
</script>
